module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

parameter WIDTH_A = 8;
parameter WIDTH_B = 8;
parameter WIDTH_OUT = 16;

reg [2:0] mul_en_out_reg;
reg [WIDTH_A-1:0] mul_a_reg;
reg [WIDTH_B-1:0] mul_b_reg;
wire [WIDTH_OUT-1:0] temp[0:7];
reg [WIDTH_OUT-1:0] sum[0:7];
reg [WIDTH_OUT-1:0] mul_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out_reg <= 1'b0;
    end else begin
        mul_en_out_reg <= {mul_en_out_reg[WIDTH_OUT-2:0], mul_en_in};
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 'd0;
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_b_reg <= 'd0;
    end else begin
        if (mul_en_in) begin
            mul_b_reg <= mul_b;
        end
    end
end

genvar i;
generate
    for (i = 0; i < WIDTH_B; i = i + 1) begin : pp_gen
        assign temp[i] = (mul_b_reg[i]) ? {{(WIDTH_OUT-WIDTH_A){1'b0}}, mul_a_reg} << i : 'd0;
    end
endgenerate

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum[0] <= 'd0;
        sum[1] <= 'd0;
        sum[2] <= 'd0;
        sum[3] <= 'd0;
        sum[4] <= 'd0;
        sum[5] <= 'd0;
        sum[6] <= 'd0;
        sum[7] <= 'd0;
    end else begin
        sum[0] <= temp[0];
        sum[1] <= temp[1] + temp[2];
        sum[2] <= temp[3] + temp[4];
        sum[3] <= temp[5] + temp[6];
        sum[4] <= temp[7];
        sum[5] <= 'd0;
        sum[6] <= 'd0;
        sum[7] <= 'd0;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out_reg <= 'd0;
    end else begin
        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3] + sum[4] + sum[5] + sum[6] + sum[7];
    end
end

assign mul_out = (mul_en_out_reg[WIDTH_OUT-1]) ? mul_out_reg : 'd0;

assign mul_en_out = mul_en_out_reg[WIDTH_OUT-1];
endmodule
